describe('Async Form Submission', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should disable the submit button while the form is submitting', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="email"]').type('testuser@example.com');
        cy.get('button[type="submit"]').should('not.be.disabled');

        cy.get('button[type="submit"]').click();
        cy.get('button[type="submit"]').should('be.disabled');

        // Simulate async operation
        cy.wait(2000); // Adjust time as necessary for the async operation to complete
        cy.get('button[type="submit"]').should('not.be.disabled');
    });

    it('should not allow multiple submissions', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="email"]').type('testuser@example.com');
        cy.get('button[type="submit"]').click();
        cy.get('button[type="submit"]').should('be.disabled');

        // Attempt to click submit again before async operation completes
        cy.get('button[type="submit"]').click();
        cy.get('button[type="submit"]').should('still.be.disabled');

        // Simulate async operation
        cy.wait(2000); // Adjust time as necessary for the async operation to complete
        cy.get('button[type="submit"]').should('not.be.disabled');
    });
});
